using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: HasData() no longer accepts navigation properties
        // or complex expressions like DateTime.UtcNow evaluated at migration time.
        // Use a fixed seed value instead.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// --- Cosmos DB context demonstrating EF Core 9 breaking changes ---

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=C2y6yDjf5/R+ob0N8A7Cgv30VRDJIWEHLM+4QDU5DE2nQ9nDuVTqobD4b8mGGyPMbIZnqyMsEcaGQy67XIw/Jw==",
            "EfApp");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: Cosmos provider now uses "$type" instead of
        // "Discriminator" by default for polymorphic type discrimination.
        // To maintain backward compatibility with existing documents that use
        // "Discriminator", explicitly configure it:
        modelBuilder.Entity<Product>()
            .HasDiscriminator<string>("Discriminator");

        modelBuilder.Entity<Product>()
            .ToContainer("Products")
            .HasPartitionKey(p => p.Category);
    }
}

class Product
{
    public string Id { get; set; } = null!;
    public string Name { get; set; } = null!;
    public string Category { get; set; } = null!;
}

// --- Cosmos DB query service demonstrating sync-to-async migration ---

class CosmosQueryService
{
    // EF Core 9 breaking change: Synchronous I/O on Cosmos DB provider is no longer
    // supported. All queries must use async methods (ToListAsync, FirstOrDefaultAsync, etc.)
    // Previously: _context.Products.ToList() — now throws InvalidOperationException.
    async Task<List<Product>> GetProductsByCategoryAsync(CosmosDbContext context, string category)
    {
        return await context.Products
            .Where(p => p.Category == category)
            .ToListAsync();
    }

    async Task<Product?> GetProductByIdAsync(CosmosDbContext context, string id)
    {
        return await context.Products
            .FirstOrDefaultAsync(p => p.Id == id);
    }
}

